package com.example;

public class User {
    private String name;
    private int age;
    private String email;

    public User() {}

    public User(String name, int age, String email) {
        this.name = name;
        this.age = age;
        this.email = email;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public int getAge() {
        return age;
    }

    public void setAge(int age) {
        this.age = age;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    @Override
    public String toString() {
        return "User{name='" + name + "', age=" + age + ", email='" + email + "'}";
    }
}

package com.example;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.Arrays;
import java.util.List;

public class JsonApp {
    public static void main(String[] args) {
        Gson gson = new GsonBuilder().setPrettyPrinting().create();

        // Generate JSON from object
        User user = new User("Alice", 30, "alice@example.com");
        String json = gson.toJson(user);
        System.out.println("Generated JSON:");
        System.out.println(json);

        // Parse JSON to object
        String inputJson = "{ \"name\": \"Bob\", \"age\": 25, \"email\": \"bob@example.com\" }";
        System.out.println("\nParsing JSON:");
        System.out.println(inputJson);
        User parsedUser = gson.fromJson(inputJson, User.class);
        System.out.println("Parsed object: " + parsedUser);

        // Parse list of objects
        String listJson = "[ { \"name\": \"Charlie\", \"age\": 35, \"email\": \"charlie@example.com\" } ]";
        System.out.println("\nParsing list of objects:");
        Type userType = new TypeToken<List<User>>() {}.getType();
        List<User> users = gson.fromJson(listJson, userType);
        System.out.println("Parsed list: " + users);
    }
}
